#!/usr/bin/env bash
set -euo pipefail
# shellcheck source=../../../lib/common.sh
. "$AF_ROOT/lib/common.sh"
af_load_config

# SSH alias for the host. ~/.ssh/config is owned by your dotfiles, so we write
# a separate file and ask you to Include it once.
conf="$AF_HOME/ssh_config"
run mkdir -p "$AF_HOME"
if [[ "$AF_DRY_RUN" != 1 ]]; then
  cat > "$conf" <<SSH
# Generated by agentfiles (roles/master/steps/30-ssh.sh). Do not edit; re-run bootstrap.
Host agent $AF_HOST_TAILNET
    HostName $AF_HOST_TAILNET
    User $AF_HOST_USER
    ServerAliveInterval 30
    ServerAliveCountMax 4
    ControlMaster auto
    ControlPath ~/.ssh/cm-%r@%h:%p
    ControlPersist 10m
SSH
fi
ok "Wrote $conf"

if grep -qs "Include $conf" "$HOME/.ssh/config" 2>/dev/null; then
  ok "~/.ssh/config already includes it"
else
  manual "Add this as the FIRST line of ~/.ssh/config (or your dotfiles ssh config):  Include $conf"
fi
manual "Copy your public key to the host: ssh-copy-id agent"
